// Gelen payload'i dogrula ve normalize et.
// Agent ciktisina korumasiz guvenmiyoruz: eksik alan veya bilinmeyen
// karar gelirse akis hata dalina gider, sessizce devam etmez.
// ONAY KURALI BURADA YOK: onay_gerekli_mi tek yerde, karar_tool.py'de
// uretilir; n8n yalniz dogrular ve yonlendirir.
const ZORUNLU = ['tarih', 'karar', 'aciliyet'];
const GECERLI_KARARLAR = ['siparis_ver', 'bekle', 'indirim_uygula', 'insana_sor'];

const cikti = [];
for (const item of $input.all()) {
  const g = item.json.body ?? item.json;

  const eksik = ZORUNLU.filter(a => g[a] === undefined || g[a] === null || g[a] === '');
  let hata = null;
  if (eksik.length > 0) {
    hata = 'Eksik alan: ' + eksik.join(', ');
  } else if (!GECERLI_KARARLAR.includes(g.karar)) {
    hata = 'Bilinmeyen karar degeri: ' + g.karar;
  }

  cikti.push({ json: {
    ...g,
    gecerli: hata === null,
    hata_mesaji: hata,
    onay_gerekli_mi: Boolean(g.onay_gerekli_mi),
    onay_sebebi: g.onay_sebebi ?? '',
    alindi: new Date().toISOString()
  }});
}
return cikti;

