parameters.jsCode:
// Telegram girisi icin koprü node.
// FastAPI yaniti {cevap, tool_isimleri, karar:{...}} seklinde IC ICEDIR.
// Karar Dogrula ise DUZ bir nesne bekler (webhook payload'i gibi). Burada
// karar nesnesi duzlestirilir ve izlenebilirlik alanlari eklenir. Boylece
// webhook ve Telegram girisleri AYNI karar hattini besler.
const cikti = [];
for (const item of $input.all()) {
  const y = item.json;
  const k = y.karar || {};
  cikti.push({ json: {
    ...k,
    tool_zinciri: (y.tool_isimleri || []).join(' -> '),
    tool_sayisi: y.tool_sayisi ?? 0,
    agent_cevabi: y.cevap || '',
    kaynak: 'telegram',
    chat_id: String($('Telegram Trigger').first().json.message.chat.id),
  }});
}
return cikti;

// Buton basmasini (callback_query) ayristirir.
// callback_data bicimleri — Telegram 64 bayt sinir koyar, kisa tutuldu:
//   ok:<karar_id>              -> onay
//   no:<karar_id>              -> red, once sebep sorulacak
//   rs:<sebep_kodu>:<karar_id> -> red sebebi secildi
const cikti = [];
for (const item of $input.all()) {
  const cq = item.json.callback_query || {};
  const veri = String(cq.data || '');
  const parca = veri.split(':');
  const tip = parca[0];

  let aksiyon = 'bilinmeyen', karar_id = '', sebep_kodu = null;
  if (tip === 'ok')      { aksiyon = 'onay';       karar_id = parca[1] || ''; }
  else if (tip === 'no') { aksiyon = 'sebep_sor';  karar_id = parca[1] || ''; }
  else if (tip === 'rs') { aksiyon = 'red';        sebep_kodu = parca[1] || 'diger';
                           karar_id = parca[2] || ''; }

  cikti.push({ json: {
    aksiyon, karar_id, sebep_kodu,
    callback_id: cq.id,
    chat_id: String(cq.message?.chat?.id || ''),
    message_id: cq.message?.message_id,
    kullanici: cq.from?.username || cq.from?.first_name || 'bilinmeyen',
  }});
}
return cikti;
